"use client";

import { useEffect, useRef, type CSSProperties } from "react";

/* ----------------------------------------------------------------------------
   Orba core — raw WebGL shader orb runtime. No dependencies.

   An orb is a full-screen triangle rendered into a transparent canvas by a
   fragment shader. Every orb declares a parameter schema (sliders + colors);
   the values are uploaded as uniforms each frame from a ref, so a controls
   panel can tune them live without ever remounting the canvas (a remount would
   drop the WebGL context).

   Animation model: every state synthesizes two volume signals — input (user
   speech energy) and output (agent speech energy) — smooths them, and the
   shaders react to those. The flow clock's speed itself follows the output
   volume, so orbs visibly quicken when the agent is talking.
---------------------------------------------------------------------------- */

export type OrbState = "idle" | "listening" | "thinking" | "speaking";

export const ORB_STATES = ["idle", "listening", "thinking", "speaking"] as const;

function clamp01(n: number) {
  return Math.min(1, Math.max(0, n));
}

/** Per-state [input, output] volume synthesis. */
function targetVolumes(state: OrbState, t: number): [number, number] {
  switch (state) {
    case "idle":
      return [0, 0.3];
    case "listening":
      return [clamp01(0.55 + Math.sin(t * 3.2) * 0.35), 0.45];
    case "speaking":
      return [
        clamp01(0.65 + Math.sin(t * 4.8) * 0.22),
        clamp01(0.75 + Math.sin(t * 3.6) * 0.22)
      ];
    case "thinking": {
      const base = 0.38 + 0.07 * Math.sin(t * 0.7);
      const wander = 0.05 * Math.sin(t * 2.1) * Math.sin(t * 0.37 + 1.2);
      return [clamp01(base + wander), clamp01(0.48 + 0.12 * Math.sin(t * 1.05 + 0.6))];
    }
  }
}

/* ------------------------------ param schema ------------------------------- */

export interface OrbParamDef {
  key: string;
  label: string;
  min: number;
  max: number;
  step: number;
  default: number;
  /**
   * Rate params. The engine integrates them into a clock
   * (`clock += dt * value * volumeSpeed`) and uploads the clock instead of the
   * raw value, so changing the rate never jumps the phase — the motion speeds
   * up or slows down rather than snapping to a new position.
   */
  integrate?: boolean;
}

export interface OrbColorDef {
  key: string;
  label: string;
  /** hex, e.g. `#ff8b73` */
  default: string;
}

export interface OrbVariant {
  key: string;
  label: string;
  note: string;
  /** GLSL fragment shader body. Uniform declarations are generated for you. */
  frag: string;
  params: OrbParamDef[];
  colors: OrbColorDef[];
  /**
   * Per-state parameter targets. The engine glides each param toward the
   * active state's preset. Params passed explicitly via the `params` prop
   * always win over the preset.
   */
  statePresets?: Partial<Record<OrbState, Record<string, number>>>;
}

export type OrbParamValues = Partial<Record<string, number>>;
export type OrbColorValues = Partial<Record<string, string>>;

/** Every param and color at its schema default. */
export function defaultValuesFor(variant: OrbVariant): {
  params: Record<string, number>;
  colors: Record<string, string>;
} {
  return {
    params: Object.fromEntries(variant.params.map((p) => [p.key, p.default])),
    colors: Object.fromEntries(variant.colors.map((c) => [c.key, c.default]))
  };
}

export function hexToRgb(hex: string): [number, number, number] {
  let h = hex.replace("#", "").trim();
  if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  const n = parseInt(h, 16);
  if (h.length !== 6 || Number.isNaN(n)) return [1, 1, 1];
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

/* ------------------------------- GLSL shared ------------------------------- */

const VERT = `
attribute vec2 aPos;
void main() { gl_Position = vec4(aPos, 0.0, 1.0); }
`;

/**
 * Prelude prepended to every orb fragment shader: uniforms, value noise, fbm,
 * and the centered aspect-corrected UV helper.
 */
export const ORB_GLSL_HELPERS = `
precision highp float;
uniform vec2 uRes;
uniform float uTime;   // slow ambient clock (half real-time)
uniform float uAnim;   // flow clock — its speed follows the output volume
uniform float uInput;  // input volume 0..1: user speech energy
uniform float uOutput; // output volume 0..1: agent speech energy

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}
float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = p * 2.03 + vec2(11.7, 7.3);
    a *= 0.5;
  }
  return v;
}
vec2 orbUV() { return (2.0 * gl_FragCoord.xy - uRes) / min(uRes.x, uRes.y); }

// GLSL ES 1.0 has no tanh() — it arrived in ES 3.0. Shader-golf listings lean
// on it as a tone-mapper, so it ships here. Clamped against exp() overflow;
// accurate for the non-negative accumulators those shaders produce.
vec3 tanh3(vec3 x) {
  x = clamp(x, -10.0, 10.0);
  vec3 e = exp(2.0 * x);
  return (e - 1.0) / (e + 1.0);
}
`;

function paramUniformDecls(variant: OrbVariant): string {
  return [
    ...variant.params.map((p) => `uniform float uP_${p.key};`),
    ...variant.colors.map((c) => `uniform vec3 uC_${c.key};`)
  ].join("\n");
}

/* ------------------------------- engine ------------------------------------ */

function compile(gl: WebGLRenderingContext, type: number, src: string): WebGLShader | null {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, src);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.error("[orba] shader compile error:", gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

export interface ShaderOrbProps {
  /** The orb definition: shader + param schema + state presets. */
  variant: OrbVariant;
  /** Drives the synthesized volume signals. Defaults to `"idle"`. */
  state?: OrbState;
  /** Rendered size in CSS pixels. Ignored when `className` sizes the canvas. */
  size?: number;
  /** Explicit param overrides. Any key present here wins over the state preset. */
  params?: OrbParamValues;
  /** Explicit color overrides, as hex strings. */
  colors?: OrbColorValues;
  /** Freeze the animation on the current frame. */
  paused?: boolean;
  /**
   * Stop rendering while the orb is scrolled out of view. Defaults to `true` —
   * a page full of orbs would otherwise run a WebGL loop per card.
   */
  pauseOffscreen?: boolean;
  /** Device-pixel-ratio ceiling. Defaults to `2`. */
  maxDpr?: number;
  className?: string;
  style?: CSSProperties;
  /** Accessible label. When omitted the canvas is hidden from assistive tech. */
  ariaLabel?: string;
}

export function ShaderOrb({
  variant,
  state = "idle",
  size,
  params,
  colors,
  paused = false,
  pauseOffscreen = true,
  maxDpr = 2,
  className,
  style,
  ariaLabel
}: ShaderOrbProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Live refs: the render loop reads these every frame, so changing a param
  // never re-runs the GL setup effect (which would drop the context). Synced in
  // an effect rather than during render — a ref write during render is unsafe
  // under concurrent rendering, and the loop picks the new value up on the very
  // next frame anyway.
  const stateRef = useRef<OrbState>(state);
  const paramsRef = useRef<OrbParamValues | undefined>(params);
  const colorsRef = useRef<OrbColorValues | undefined>(colors);
  const pausedRef = useRef(paused);

  useEffect(() => {
    stateRef.current = state;
    paramsRef.current = params;
    colorsRef.current = colors;
    pausedRef.current = paused;
  }, [state, params, colors, paused]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const gl = canvas.getContext("webgl", {
      alpha: true,
      antialias: true,
      premultipliedAlpha: true
    });
    if (!gl || gl.isContextLost()) return;

    const vs = compile(gl, gl.VERTEX_SHADER, VERT);
    const fs = compile(
      gl,
      gl.FRAGMENT_SHADER,
      ORB_GLSL_HELPERS + paramUniformDecls(variant) + variant.frag
    );
    if (!vs || !fs) return;

    const prog = gl.createProgram();
    if (!prog) return;
    gl.attachShader(prog, vs);
    gl.attachShader(prog, fs);
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
      console.error("[orba] program link error:", gl.getProgramInfoLog(prog));
      return;
    }
    gl.useProgram(prog);

    const buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    const aPos = gl.getAttribLocation(prog, "aPos");
    gl.enableVertexAttribArray(aPos);
    gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);

    const uRes = gl.getUniformLocation(prog, "uRes");
    const uTime = gl.getUniformLocation(prog, "uTime");
    const uAnim = gl.getUniformLocation(prog, "uAnim");
    const uInput = gl.getUniformLocation(prog, "uInput");
    const uOutput = gl.getUniformLocation(prog, "uOutput");

    const paramLocs = variant.params.map((p) => ({
      def: p,
      loc: gl.getUniformLocation(prog, `uP_${p.key}`)
    }));
    const colorLocs = variant.colors.map((c) => ({
      def: c,
      loc: gl.getUniformLocation(prog, `uC_${c.key}`)
    }));

    /* --- sizing: track the element box, not a one-shot measurement --------- */
    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, maxDpr);
      const w = Math.max(1, Math.round(canvas.clientWidth * dpr));
      const h = Math.max(1, Math.round(canvas.clientHeight * dpr));
      if (canvas.width === w && canvas.height === h) return;
      canvas.width = w;
      canvas.height = h;
      gl.viewport(0, 0, w, h);
      gl.uniform2f(uRes, w, h);
    };
    resize();

    const resizeObserver =
      typeof ResizeObserver !== "undefined" ? new ResizeObserver(resize) : null;
    resizeObserver?.observe(canvas);

    /* --- visibility: don't burn a render loop on an offscreen orb ---------- */
    let visible = !pauseOffscreen;
    const intersectionObserver =
      pauseOffscreen && typeof IntersectionObserver !== "undefined"
        ? new IntersectionObserver(
            (entries) => {
              visible = Boolean(entries[0]?.isIntersecting);
              if (visible) {
                last = performance.now() / 1000;
              }
            },
            { rootMargin: "150px 0px", threshold: 0 }
          )
        : null;
    if (intersectionObserver) {
      intersectionObserver.observe(canvas);
    } else {
      visible = true;
    }

    const reduceMotion =
      typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    /* --- driver state ------------------------------------------------------ */
    let tSec = 0;
    // random phase so two orbs on the same page never look synchronized
    let anim = Math.random() * 100;
    let speed = 0.1;
    const cur = { in: 0, out: 0.3 };
    const presets = variant.statePresets;
    const paramCur: Record<string, number> = {};
    const paramClocks: Record<string, number> = {};
    const [initialIn, initialOut] = targetVolumes(stateRef.current, 0);
    cur.in = initialIn;
    cur.out = initialOut;
    let last = performance.now() / 1000;
    let raf = 0;

    const uploadAndDraw = (dt: number) => {
      const [tin, tout] = targetVolumes(stateRef.current, tSec);
      const kVol = 1 - Math.exp(-dt * 12);
      cur.in += (tin - cur.in) * kVol;
      cur.out += (tout - cur.out) * kVol;

      // flow speed follows the output volume, then is smoothed
      const targetSpeed = 0.1 + (1 - Math.pow(cur.out - 1, 2)) * 0.9;
      speed += (targetSpeed - speed) * (1 - Math.exp(-dt * 7));
      anim += dt * speed;

      gl.uniform1f(uTime, tSec * 0.5);
      gl.uniform1f(uAnim, anim);
      gl.uniform1f(uInput, cur.in);
      gl.uniform1f(uOutput, cur.out);

      // Resolution order per param: explicit prop → active state preset →
      // schema default. Values glide rather than snap.
      const kParam = 1 - Math.exp(-dt * 1.8);
      const liveParams = paramsRef.current;
      const statePreset = presets?.[stateRef.current];

      for (const { def, loc } of paramLocs) {
        const explicit = liveParams?.[def.key];
        const target =
          typeof explicit === "number" ? explicit : (statePreset?.[def.key] ?? def.default);
        const curVal = paramCur[def.key] ?? target;
        const next = curVal + (target - curVal) * kParam;
        paramCur[def.key] = next;

        if (def.integrate) {
          const clock =
            (paramClocks[def.key] ?? (paramClocks[def.key] = Math.random() * 100)) +
            dt * speed * next;
          paramClocks[def.key] = clock;
          gl.uniform1f(loc, clock);
        } else {
          gl.uniform1f(loc, next);
        }
      }

      const liveColors = colorsRef.current;
      for (const { def, loc } of colorLocs) {
        const [cr, cg, cb] = hexToRgb(liveColors?.[def.key] ?? def.default);
        gl.uniform3f(loc, cr, cg, cb);
      }

      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    };

    if (reduceMotion) {
      // One representative frame, then stop. `dt` is large enough that the
      // param glide lands on its target immediately.
      tSec = 1;
      uploadAndDraw(1);
      return () => {
        resizeObserver?.disconnect();
        intersectionObserver?.disconnect();
        gl.deleteProgram(prog);
        gl.deleteShader(vs);
        gl.deleteShader(fs);
        gl.deleteBuffer(buf);
      };
    }

    const loop = () => {
      raf = requestAnimationFrame(loop);
      const now = performance.now() / 1000;
      const dt = Math.min(now - last, 0.05);
      last = now;
      if (!visible || pausedRef.current) return;
      tSec += dt;
      uploadAndDraw(dt);
    };
    loop();

    return () => {
      cancelAnimationFrame(raf);
      resizeObserver?.disconnect();
      intersectionObserver?.disconnect();
      // Free GL objects but leave the context alive: React re-runs this effect
      // on the same canvas in dev StrictMode, and a lost context can't compile.
      gl.deleteProgram(prog);
      gl.deleteShader(vs);
      gl.deleteShader(fs);
      gl.deleteBuffer(buf);
    };
  }, [variant, pauseOffscreen, maxDpr]);

  const sizeStyle: CSSProperties =
    size === undefined ? {} : { width: size, height: size };

  return (
    <canvas
      // A lost WebGL context can't be reused, so each variant gets a fresh canvas.
      key={variant.key}
      ref={canvasRef}
      className={className}
      style={{ display: "block", ...sizeStyle, ...style }}
      role={ariaLabel ? "img" : undefined}
      aria-label={ariaLabel}
      aria-hidden={ariaLabel ? undefined : true}
    />
  );
}

/*
 * Deliberately not a `"use client"` module — see the note in `orb-hydrogen.tsx`.
 *
 * Note for editors: the shader lives in a template literal, so its comments
 * must not contain backticks.
 */
import { ShaderOrb, type OrbVariant, type ShaderOrbProps } from "@/components/ui/orba-core";

/* ----------------------------------------------------------------------------
   Quasar — an emissive swept core with a jet, given a glassy surface.

   The structure comes from the golfed listing this was ported from. Its one
   load-bearing line is easy to miss:

     a = mix(dot(a -= .57, p) * a, p, cos(s)) - sin(s) * cross(a, p)

   Expanding mix(x, y, f) = x(1-f) + y*f gives

     p*cos(s) + a(a.p)(1 - cos s) - sin(s)(a x p)

   which is the RODRIGUES formula: p rotated about the axis a by angle -s, with
   the turbulence applied in that rotating frame.

   uP_axisBias is that axis, and it has three regimes:

     0.5774   an exact unit axis, so the sweep is a true rotation.
     0.57     the original. length(vec3(0.57)) is 0.987, so it is a rotation
              with a small constant scale baked in.
     0        the formula COLLAPSES to p * cos(s) — no rotation at all, only a
              rhythmic radial pulse. A different effect rather than a weaker
              one, and the default here.

   The axis originally came from subtracting 0.57 from a local that is never
   assigned, which works only because the value happens to start at zero.
   Uninitialised locals are UNDEFINED in GLSL ES 1.0, so it is explicit below.

   This is EMISSIVE, not a solid. The glassiness is added as surface character
   over the emission — a fresnel rim sheen and per-channel offset of the palette
   ramp for chromatic fringing — rather than by putting the effect inside a
   refracting ball, which buries the jet and flattens the whole thing.
---------------------------------------------------------------------------- */

/*
 * Step counts are `#define`s: ES 1.0 requires constant loop bounds.
 */
const QUASAR_FRAG = `
#define STEPS 70
#define TURB 8
#define AA 1

// Volume-reactive values, resolved once per fragment in main().
float quasarSwirl;
float quasarExposure;

vec2 quasarRender(vec2 fragCoord) {
  float animTime = uP_speed; // integrated clock

  vec2 uv = (2.0 * fragCoord - uRes) / min(uRes.x, uRes.y);
  vec3 ro = vec3(0.0, 0.0, uP_camDist);
  vec3 rd = normalize(vec3(uv, -uP_focal));

  float emission = 0.0;
  float structW = 0.0;
  float z = 0.0;
  float d = 0.0;

  // transmittance carried front-to-back — see the diffusion note in the loop
  float T = 1.0;

  /*
    The sweep angle.

    The original decrements this by iTime on EVERY march step. That works on
    Shadertoy only because iTime is small — a few seconds — so the per-step
    angle change stays modest. Our clock is integrated and unbounded (it starts
    at a random phase and grows for as long as the page is open), so decrementing
    by it per step makes the angle change grow without limit: cos(s) then jumps
    almost randomly between neighbouring steps, the structure degenerates into
    aliased noise, and total brightness swings wildly as the clock drifts. That
    is what made this orb look different every time it was sampled.

    Fixed per-step decrement, with the clock as the starting PHASE instead.
  */
  float s = animTime;

  for (int it = 0; it < STEPS; it++) {
    vec3 p = ro + rd * z;

    // explicit — the original relies on an unassigned local being zero
    vec3 a = vec3(-uP_axisBias);

    s -= quasarSwirl;

    /*
      The angle is the running term PLUS the clock as a flat offset. animTime is
      constant across every step of a frame, so adding it here animates the
      sweep without compounding per step — which is exactly the distinction the
      original loses by decrementing s by the clock itself.

      Note s is dual-purpose, as in the golfed original: it is overwritten below
      by the structure term and fed back in on the next iteration. That feedback
      is deliberate and is where the chaotic character comes from; it only had to
      stop being scaled by an unbounded clock.
    */
    float ang = s + animTime;

    // Rodrigues: p rotated about a by -ang. At axisBias 0 this degenerates to
    // p * cos(ang), a pure radial pulse — see the note in the header.
    a = mix(dot(a, p) * a, p, cos(ang)) - sin(ang) * cross(a, p);

    // structure term — distance from the sweep axis, and the radial falloff.
    // Also the value fed back into the angle on the next step.
    s = sqrt(length(a.xz - a.y));

    // turbulence in the rotating frame, frequency climbing per octave
    for (int j = 0; j < TURB; j++) {
      float dj = float(j) + 2.0;
      a += sin(a * dj - animTime).yzx / dj;
    }

    // dot(a, a/a) in the original is just the component sum; written out
    // because a/a is NaN wherever a component is exactly zero
    d = length(sin(a) + dot(a, vec3(1.0)) * uP_densityBias) * s / uP_stepScale;
    z += d;

    /*
      Guard both divisors: s and d reach zero on the axis, and one Inf poisons
      the whole accumulation for that pixel.

      The CLAMP matters as much as the guards. Where s and d both go small on
      the same step, 1/(s*d) spikes by orders of magnitude and that single
      sample dominates the entire 70-step sum — so at some sweep phases the orb
      blew out to flat white while neighbouring phases looked correct. Bounding
      each step's contribution keeps total brightness stable across the whole
      cycle instead of leaving it hostage to whether a ray happened to graze
      the axis.
    */
    float w = min(1.0 / (max(s, 1e-3) * max(d, 1e-4)), uP_stepClamp);

    /*
      Spherical envelope plus a constant floor.

      Unbounded, the sweep throws lobes well off-centre and this reads as a
      lopsided comet streak rather than an orb. Bounding alone is still not
      enough — the structure is lopsided INSIDE the ball too, so the bright
      regions form a blob. uP_fill gives every interior sample a floor, which
      guarantees the sphere and lets the structure ride on top as detail.
      Set fill to 0 for the bare unbounded effect.
    */
    w = (w + uP_fill) * smoothstep(uP_envRadius, uP_envRadius * uP_envCore, length(p));

    /*
      Light diffusion.

      Without transmittance every step adds equally no matter how deep it sits,
      so the orb is a flat additive smear with no interior — the far wall reads
      exactly as bright as the near one. Carrying T front-to-back and attenuating
      it by what has already been passed through makes the medium veil itself:
      near structure occludes far structure, the silhouette gains depth, and the
      emission softens the way light actually does through a scattering volume.

      Beer-Lambert, same as orb-nimbus, but driven by the emission itself rather
      than a separate density field — this orb IS its own medium.
    */
    emission += T * w;
    structW += T * w * s;

    T *= exp(-w * uP_scatter);
    if (T < 0.004) break;
  }

  return vec2(emission, structW);
}

void main() {
  quasarSwirl = uP_swirl * (1.0 + 0.7 * uInput);
  quasarExposure = uP_exposure * (1.0 - 0.35 * uOutput);

  vec2 acc = vec2(0.0);
#if AA > 1
  for (int mx = 0; mx < AA; mx++) {
    for (int my = 0; my < AA; my++) {
      vec2 offset = vec2(float(mx), float(my)) / float(AA) - 0.5;
      acc += quasarRender(gl_FragCoord.xy + offset);
    }
  }
  acc /= float(AA * AA);
#else
  acc = quasarRender(gl_FragCoord.xy);
#endif

  float emission = acc.x;

  float e = tanh3(vec3(emission / max(quasarExposure, 1.0))).x;
  e = pow(clamp(e, 0.0, 1.0), uP_contrast);

  /*
    Ramp coordinate: the emission-weighted mean of the structure term, which is
    distance from the sweep axis. Low along the jet and nucleus, high out in the
    lobes, so it varies strongly ACROSS the image.

    Depth was tried here first and does not work — the emission-weighted mean
    depth is nearly identical for every pixel, so the ramp collapses and the orb
    comes out one washed colour whatever the endpoints are.
  */
  float axisN = acc.y / max(emission, 1e-4);

  /*
    Chromatic fringing: each channel reads the palette ramp at a slightly
    different point along that axis coordinate. Cheaper than refracting three
    rays and it keeps the emission intact — the jet stays a jet — while the
    lobe edges separate into colour the way glass does.
  */
  float sp = uP_chroma * uP_structRef;
  vec3 t = vec3(
    smoothstep(0.0, uP_structRef, axisN - sp),
    smoothstep(0.0, uP_structRef, axisN),
    smoothstep(0.0, uP_structRef, axisN + sp)
  );

  vec3 col = vec3(
    mix(uC_core, uC_halo, t.r).r,
    mix(uC_core, uC_halo, t.g).g,
    mix(uC_core, uC_halo, t.b).b
  ) * e;

  // whiten the hottest cores so the jet and nucleus read as incandescent
  col = mix(col, vec3(1.0), smoothstep(uP_whiteAt, 1.0, e) * uP_coreWhite);

  /*
    Glassy sheen. The emission has no surface, so a fresnel-style rim brightening
    keyed off screen radius gives it one: bright right at the silhouette, gone by
    the middle. It is what makes the ball look like it has a skin rather than
    being a cloud.
  */
  float r2d = length(orbUV());
  float rim = pow(clamp(r2d / max(uP_rimAt, 0.001), 0.0, 1.0), uP_rimPow);
  col += uC_rim * rim * uP_rim * smoothstep(0.02, 0.25, e);

  /*
    Bloom.

    The same emission tone-mapped through a much lower knee. tanh saturates far
    earlier, so faint outer emission that the main curve leaves near-black comes
    up to full — the light appears to spill past the core into the halo. A real
    separable blur would need a second pass and a framebuffer; this gets the
    read for one extra tanh, because the emission buffer already falls off
    smoothly outward.
  */
  float bloom = tanh3(vec3(emission / max(quasarExposure * uP_bloomKnee, 1.0))).x;
  bloom = pow(clamp(bloom, 0.0, 1.0), uP_bloomPow) * uP_bloom;
  col += mix(uC_core, uC_halo, t.g) * bloom;

  // the bloom has to carry its own coverage, or it multiplies against an alpha
  // that is already zero out where the halo lives and never shows
  float a = clamp(max(e * uP_alphaGain, bloom), 0.0, 1.0);

  // Fade colour as well as alpha — with premultiplied output, fading only alpha
  // leaves the pixel emitting at full brightness up to the cutoff, which reads
  // as a hard rim.
  float fade = 1.0 - smoothstep(uP_edgeFade, 1.0, r2d);
  col *= fade;
  a *= fade;

  // Emitted light, so rgb is already premultiplied — do NOT scale by alpha
  // again (see the same note in orb-corona).
  gl_FragColor = vec4(col, a);
}
`;

